/**
 * Turns compiled plans into `.qala/queries.gen.ts`: per query, its SQL, a typed parameter mapper and a
 * typed result assembler with the row shapes spelled out, so scriptc compiles decoding to native code.
 * The types come from the declarations (`import type`), so a query changed without regenerating fails
 * `tsc`. Build-time only.
 */
import type { Plan, PlanLevel, PlanParam, PlanValue } from "./compile";

export type EmitEntry = {
  /** Export name of the query (unique across the app). */
  name: string;
  /** Import path of the declaring module, relative to the generated file (no extension). */
  from: string;
  /** The export name in that module (usually equal to `name`). */
  exportName: string;
  plan: Plan;
};

const HEADER = "// Generated by `qala generate`. Do not edit: changes are overwritten.\n";

function paramExpr(p: PlanParam): string {
  const v = `p.${p.name}`;
  if (p.array) return p.optional ? `${v} === undefined || ${v} === null ? null : pgArray(${v})` : `pgArray(${v})`;
  return p.optional ? `${v} ?? null` : v;
}

function valueExpr(f: PlanValue, rowType: string): string {
  const v = `v[${f.index}]`;
  const isNull = `${v} === null || ${v} === undefined`;
  switch (f.kind) {
    case "integer":
    case "bigint":
    case "number":
      return f.nullable ? `${isNull} ? null : Number(${v})` : `Number(${v})`;
    case "boolean":
      return f.nullable ? `${isNull} ? null : ${v} === "t"` : `${v} === "t"`;
    case "datetime":
      return f.nullable ? `${isNull} ? null : pgIso(${v})` : `pgIso(${v} ?? "")`;
    default: {
      const base = f.nullable ? `${v} ?? null` : `${v} ?? ""`;
      return f.enumField ? `(${base}) as ${rowType}[${JSON.stringify(f.name)}]` : base;
    }
  }
}

function key(name: string): string {
  return /^[A-Za-z_$][\w$]*$/.test(name) ? name : JSON.stringify(name);
}

function objectExpr(level: PlanLevel, rowType: string): string {
  const parts: string[] = [];
  for (const f of level.fields) {
    if (f.type === "value") parts.push(`${key(f.name)}: ${valueExpr(f, rowType)}`);
    else {
      const k = `v[${f.keyIndex}] ?? ""`;
      parts.push(`${key(f.name)}: m${f.level}.get(${k}) ?? ${relationEmpty(f.level)}`);
    }
  }
  return `{ ${parts.join(", ")} }`;
}

let levelsInScope: PlanLevel[] = [];
function relationEmpty(level: number): string {
  return levelsInScope[level]!.cardinality === "one" ? "null" : "[]";
}

/** Element type names: `E_<query>_<level>`, derived from the declaration's types. */
function levelTypes(entry: EmitEntry): string[] {
  const { name, plan } = entry;
  const lines: string[] = [];
  for (const level of plan.levels) {
    const t = `E_${name}_${level.statement}`;
    if (level.cardinality === "root") {
      lines.push(`type ${t} = QueryRow<typeof D_${name}>;`);
      continue;
    }
    const parent = plan.levels[level.parent]!;
    const field = parent.fields.find((f) => f.type === "relation" && f.level === level.statement)!;
    const access = `E_${name}_${parent.statement}[${JSON.stringify(field.name)}]`;
    lines.push(level.cardinality === "many" ? `type ${t} = ${access}[number];` : `type ${t} = NonNullable<${access}>;`);
  }
  return lines;
}

function emitOne(entry: EmitEntry): string {
  const { name, plan } = entry;
  levelsInScope = plan.levels;
  const lines: string[] = [];
  lines.push(`type P_${name} = QueryParams<typeof D_${name}>;`, `type R_${name} = QueryResult<typeof D_${name}>;`);
  if (plan.mode !== "affected") lines.push(...levelTypes(entry));
  const steps = plan.statements.map((s) => {
    const mapped = s.params.map(paramExpr);
    return `    step<P_${name}>(${JSON.stringify(s.sql)}, (p: P_${name}): DbValue[] => [${mapped.join(", ")}]),`;
  });
  const body: string[] = [];
  if (plan.mode === "affected") {
    body.push("rs[0]!.affected");
  } else {
    const inner: string[] = [];
    for (let i = plan.levels.length - 1; i >= 1; i--) {
      const level = plan.levels[i]!;
      const t = `E_${name}_${level.statement}`;
      if (level.cardinality === "many") {
        inner.push(`    const m${i} = new Map<string, ${t}[]>();`);
        inner.push(`    for (const v of rs[${i}]!.rows) groupPush(m${i}, v[0] ?? "", ${objectExpr(level, t)});`);
      } else {
        inner.push(`    const m${i} = new Map<string, ${t}>();`);
        inner.push(`    for (const v of rs[${i}]!.rows) {`, `      const k = v[0] ?? "";`, `      if (!m${i}.has(k)) m${i}.set(k, ${objectExpr(level, t)});`, "    }");
      }
    }
    const root = plan.levels[0]!;
    const t0 = `E_${name}_0`;
    inner.push(`    const out: ${t0}[] = [];`);
    inner.push(`    for (const v of rs[0]!.rows) out.push(${objectExpr(root, t0)});`);
    inner.push(plan.mode === "first" ? "    return out.length === 0 ? null : out[0]!;" : "    return out;");
    body.push(`{\n${inner.join("\n")}\n  }`);
  }
  lines.push(`export const ${name} = compiled<P_${name}, R_${name}>(`);
  lines.push(`  ${JSON.stringify(name)},`);
  lines.push("  [", ...steps, "  ],");
  lines.push(`  (rs: RawResult[]): R_${name} => ${body.join("")},`);
  lines.push(");");
  return lines.join("\n");
}

/** The whole `.qala/queries.gen.ts`. */
export function emitQueries(entries: EmitEntry[]): string {
  const sorted = [...entries].sort((a, b) => a.name.localeCompare(b.name));
  const lines = [
    HEADER,
    'import { compiled, groupPush, pgArray, pgIso, step, type DbValue, type RawResult } from "@qala/core";',
    'import type { QueryParams, QueryResult, QueryRow } from "@qala/core/query";',
  ];
  for (const e of sorted) lines.push(`import type { ${e.exportName} as D_${e.name} } from ${JSON.stringify(e.from)};`);
  lines.push("");
  for (const e of sorted) lines.push(emitOne(e), "");
  lines.push(`/** Every compiled query, for \`run(db, Queries.x, params)\` and \`batch(db, { … })\`. */`);
  lines.push(`export const Queries = { ${sorted.map((e) => e.name).join(", ")} };`, "");
  return lines.join("\n");
}
